INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', '最高気温と最低気温の差が最も大きい月は、最も小さい月の差の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["1.73倍", "1.54倍", "1.07倍", "1.88倍", "1.23倍"]', 1, '["各月の最高気温と最低気温の差を求めると、最も大きいのは8月の31.3－16.4＝14.9℃、最も小さいのは2月の5.2－-4.5＝9.7℃。14.9÷9.7＝1.536… 答えは約1.54倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', '売上高と経費の差が最も大きい月の売上高は、差が最も小さい月の売上高の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["1.57倍", "2.67倍", "1.79倍", "2.17倍", "2.43倍"]', 3, '["差が最も大きいのは7月（76－50＝26）、最も小さいのは1月（35－24＝11）。7月の売上高76と1月の売上高35を比べる。76÷35＝2.171… 答えは約2.17倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', '休日来場者数と平日来場者数の差が最も大きい月の休日来場者数は、差が最も小さい月の休日来場者数の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["3.04倍", "3.55倍", "2.73倍", "2.07倍", "2.36倍"]', 0, '["差が最も大きいのは8月（16.1－7.4＝8.7）、最も小さいのは1月（5.3－3.6＝1.7）。8月の休日来場者数16.1と1月の休日来場者数5.3を比べる。16.1÷5.3＝3.038… 答えは約3.04倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
