INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', '生産数と不良品数の差が最も大きい月は、最も小さい月の差の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["1.47倍", "1.68倍", "1.09倍", "1.57倍", "1.30倍"]', 4, '["各月の生産数と不良品数の差を求めると、最も大きいのは7月の1091－82＝1009個、最も小さいのは1月の814－39＝775個。1009÷775＝1.302… 答えは約1.30倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', '降水量と蒸発量の差が最も大きい月は、最も小さい月の差の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["4.40倍", "6.18倍", "3.73倍", "7.04倍", "5.33倍"]', 4, '["各月の降水量と蒸発量の差を求めると、最も大きいのは7月の170－58＝112mm、最も小さいのは12月の56－35＝21mm。112÷21＝5.333… 答えは約5.33倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', 'スマホ閲覧数とPC閲覧数の差が最も大きい月は、最も小さい月の差の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.04倍", "1.71倍", "2.33倍", "2.98倍", "2.77倍"]', 2, '["各月のスマホ閲覧数とPC閲覧数の差を求めると、最も大きいのは7月の57.9－22.7＝35.2千件、最も小さいのは1月の26.9－11.8＝15.1千件。35.2÷15.1＝2.331… 答えは約2.33倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '折れ線グラフの読み取り', '最高気温と最低気温の差が最も大きい月は、最も小さい月の差の何倍か。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.02倍", "1.39倍", "1.21倍", "1.89倍", "1.66倍"]', 4, '["各月の最高気温と最低気温の差を求めると、最も大きいのは9月の24.8－9.2＝15.6℃、最も小さいのは2月の5.1－-4.3＝9.4℃。15.6÷9.4＝1.660… 答えは約1.66倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、晴海大学の授業形態別受講比率を2017年と2023年で示したものである。オンライン授業の人数は、2017年から2023年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.23倍", "1.85倍", "1.60倍", "2.40倍", "2.09倍"]', 1, '["2017年のオンライン授業＝5,000人×44%＝2,200.00人。2023年のオンライン授業＝8,500人×48%＝4,080.00人。4,080.00÷2,200.00＝1.855… 答えは約1.85倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、若葉量販店の家電カテゴリ別販売台数を2018年と2023年で示したものである。一般家電の台数は、2018年から2023年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["1.26倍", "2.11倍", "1.99倍", "1.64倍", "1.43倍"]', 3, '["2018年の一般家電＝36万台×51%＝18.36万台。2023年の一般家電＝58万台×52%＝30.16万台。30.16÷18.36＝1.643… 答えは約1.64倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、若竹サービスの利用者年代構成を2016年と2022年で示したものである。30〜40代の人数は、2016年から2022年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["1.98倍", "1.66倍", "2.21倍", "2.53倍", "2.75倍"]', 2, '["2016年の30〜40代＝32万人×32%＝10.24万人。2022年の30〜40代＝108万人×21%＝22.68万人。22.68÷10.24＝2.215… 答えは約2.21倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、西原国の輸出額の内訳を2010年と2024年で示したものである。加工品の額は、2010年から2024年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["6.49倍", "8.25倍", "9.21倍", "7.10倍", "10.69倍"]', 1, '["2010年の加工品＝101億円×8%＝8.08億円。2024年の加工品＝230億円×29%＝66.70億円。66.70÷8.08＝8.255… 答えは約8.25倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、湊市の年代別人口構成を2019年と2023年で示したものである。75歳以上の人数は、2019年から2023年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.41倍", "2.60倍", "1.60倍", "2.05倍", "1.76倍"]', 3, '["2019年の75歳以上＝16万人×11%＝1.76万人。2023年の75歳以上＝15万人×24%＝3.60万人。3.60÷1.76＝2.045… 答えは約2.05倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、旭大学の授業形態別受講比率を2017年と2023年で示したものである。対面授業の人数は、2017年から2023年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.07倍", "2.30倍", "1.48倍", "1.65倍", "1.87倍"]', 4, '["2017年の対面授業＝3,700人×54%＝1,998.00人。2023年の対面授業＝6,800人×55%＝3,740.00人。3,740.00÷1,998.00＝1.872… 答えは約1.87倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
