INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、栄サービスの利用者年代構成を2016年と2022年で示したものである。20代以下の人数は、2016年から2022年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["7.26倍", "4.76倍", "6.78倍", "6.12倍", "5.45倍"]', 3, '["2016年の20代以下＝23万人×29%＝6.67万人。2022年の20代以下＝95万人×43%＝40.85万人。40.85÷6.67＝6.124… 答えは約6.12倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、清流国の輸出額の内訳を2018年と2023年で示したものである。その他の額は、2018年から2023年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.10倍", "1.68倍", "1.90倍", "2.39倍", "1.50倍"]', 2, '["2018年のその他＝83億円×23%＝19.09億円。2023年のその他＝213億円×17%＝36.21億円。36.21÷19.09＝1.897… 答えは約1.90倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
