INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、瑞穂大学の授業形態別受講比率を2018年と2023年で示したものである。オンライン授業の人数は、2018年から2023年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.58倍", "2.37倍", "2.04倍", "1.58倍", "1.76倍"]', 2, '["2018年のオンライン授業＝5,400人×40%＝2,160.00人。2023年のオンライン授業＝8,300人×53%＝4,399.00人。4,399.00÷2,160.00＝2.037… 答えは約2.04倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：倍率計算', '次の円グラフは、陽光量販店の家電カテゴリ別販売台数を2019年と2023年で示したものである。一般家電の台数は、2019年から2023年でおよそ何倍になったか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["2.73倍", "2.43倍", "3.49倍", "3.28倍", "2.22倍"]', 0, '["2019年の一般家電＝25万台×43%＝10.75万台。2023年の一般家電＝49万台×60%＝29.40万台。29.40÷10.75＝2.735… 答えは約2.73倍。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、千歳家の月間食費内訳（総額131,000円）を示したものである。飲料費にあてられている金額として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["40,674円", "35,639円", "24,361円", "32,750円", "27,099円"]', 3, '["総額131,000円のうち飲料費は25%を占めるので、131,000×0.25＝32,750円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、白鷺大学生協の書籍販売額内訳（総額590,000円）を示したものである。雑誌にあてられている金額として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["147,158円", "118,000円", "106,267円", "86,419円", "131,120円"]', 1, '["総額590,000円のうち雑誌は20%を占めるので、590,000×0.2＝118,000円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、新緑社従業員の通勤手段構成（総数1,070人）を示したものである。自動車にあてられている人数として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["118人", "147人", "105人", "89人", "131人"]', 0, '["総数1,070人のうち自動車は11%を占めるので、1,070×0.11＝118人。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
