INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、緑風社の月間販促費内訳（総額1,740,000円）を示したものである。広告費にあてられている金額として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["428,307円", "700,149円", "651,217円", "574,200円", "517,352円"]', 3, '["総額1,740,000円のうち広告費は33%を占めるので、1,740,000×0.33＝574,200円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、東雲基金の収入源内訳（総額1,700万円）を示したものである。寄付にあてられている金額として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["437万円", "322万円", "469万円", "374万円", "281万円"]', 3, '["総額1,700万円のうち寄付は22%を占めるので、1,700×0.22＝374万円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、風見家の月間食費内訳（総額65,000円）を示したものである。その他にあてられている金額として最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["16,250円", "18,413円", "12,071円", "19,857円", "13,568円"]', 0, '["総額65,000円のうちその他は25%を占めるので、65,000×0.25＝16,250円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、琥珀市の予算内訳を2020年度と2023年度で示したものである。福祉の金額は2020年度から2023年度でおよそいくら減少したか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["約12億円減少", "約14億円減少", "約8億円減少", "約15億円減少", "約10億円減少"]', 0, '["2020年度の福祉＝60億円×35%＝21億円。2023年度の福祉＝54億円×16%＝9億円。減少額＝12億円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('tamatebako_math', '図表の読み取り', '円グラフ：構成比と金額を求める', '次の円グラフは、桜庭社の事業別売上構成を2020年度と2023年度で示したものである。事業Bの金額は2020年度から2023年度でおよそいくら増加したか。最も近いものを以下の選択肢の中から1つ選びなさい。', NULL, '["約411万円増加", "約549万円増加", "約746万円増加", "約833万円増加", "約629万円増加"]', 4, '["2020年度の事業B＝6,300万円×17%＝1,071万円。2023年度の事業B＝6,800万円×25%＝1,700万円。増加額＝629万円。"]', 4, 'published', 'ユーザー提供のオリジナル類似問題集（図表の読み取り Part3、全50問）を基に作成。グラフ画像はdata URIとしてD1に保存。', 'data:image/png;base64,', NULL);
